import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route, useNavigate, Link } from 'react-router-dom';
import SimulationDashboard from './components/SimulationDashboard';
import ComparisonCharts from './components/ComparisonCharts';
import ControlsPanel from './components/ControlsPanel';

// UI components
import { Container, Navbar, Nav, Spinner, Alert } from 'react-bootstrap';

const AppContent = () => {

    const navigate = useNavigate();

    const [results, setResults] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);

    const [parameters, setParameters] = useState({
        seed: 42,
        N: 10,
        episodes: 50,
        max_steps: 100
    });

    const algorithms = ["DQN"];

    const handleParameterChange = (name, value) => {
        setParameters({
            ...parameters,
            [name]: Number(value)
        });
    };

    const startSimulation = async () => {
        setLoading(true);
        setError(null);
        try {
            const response = await fetch("http://127.0.0.1:8000/run_simulation", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify(parameters)
            });

            if (!response.ok) {
                throw new Error(`Server returned ${response.status}`);
            }

            const data = await response.json();

            console.log("Simulation Result:", data);

            setResults(data);

            // Navigate to dashboard after simulation finishes
            navigate("/dashboard");
        } catch (err) {
            console.error("Simulation failed:", err);
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <>
            <Navbar bg="dark" variant="dark" expand="lg" className="mb-4">
                <Container>
                    <Navbar.Brand as={Link} to="/">
                        DQN Battery Scheduler
                    </Navbar.Brand>
                    <Navbar.Toggle />
                    <Navbar.Collapse>
                        <Nav className="me-auto">
                            <Nav.Link as={Link} to="/dashboard">
                                Dashboard
                            </Nav.Link>
                            <Nav.Link as={Link} to="/comparison">
                                Charts
                            </Nav.Link>
                        </Nav>
                    </Navbar.Collapse>
                </Container>
            </Navbar>

            <Container>
                <h1 className="text-center">DQN Battery Scheduling Simulation</h1>

                {error && <Alert variant="danger">{error}</Alert>}

                <ControlsPanel
                    algorithms={algorithms}
                    parameters={parameters}
                    onStartSimulation={startSimulation}
                    onParameterChange={handleParameterChange}
                    onAlgorithmChange={() => {}}
                    loading={loading}
                />

                {loading && (
                    <div className="text-center mt-3">
                        <Spinner animation="border" role="status">
                            <span className="visually-hidden">Running...</span>
                        </Spinner>
                        <div>Simulation running, please wait...</div>
                    </div>
                )}

                <Routes>
                    <Route
                        path="/dashboard"
                        element={<SimulationDashboard results={results} />}
                    />

                    <Route
                        path="/comparison"
                        element={<ComparisonCharts results={results} />}
                    />

                    <Route
                        path="/"
                        element={
                            <Card className="text-center">
                                <Card.Body>
                                    <Card.Title>Welcome to the DQN Battery Scheduling App</Card.Title>
                                    <Card.Text>
                                        Configure a simulation using the panel above, then click
                                        "Start Simulation" to begin.
                                    </Card.Text>
                                </Card.Body>
                            </Card>
                        }
                    />
                </Routes>
            </Container>
        </>
    );
};

const App = () => {
    return (
        <Router>
            <AppContent />
        </Router>
    );
};

export default App;
